int *findSwapValues(int *array1, int array1Size, int *array2, int array2Size, int *returnSize) {
  long long sum1 = 0, sum2 = 0;
  for (int i = 0; i < array1Size; i++) sum1 += array1[i];
  for (int j = 0; j < array2Size; j++) sum2 += array2[j];
  long long diff = sum2 - sum1;
  if (diff % 2 != 0) {
    *returnSize = 0;
    return NULL;
  }
  long long target = diff / 2;
  for (int i = 0; i < array1Size; i++) {
    long long need = array1[i] + target;
    for (int j = 0; j < array2Size; j++) {
      if (array2[j] == need) {
        int *res = (int *)malloc(sizeof(int) * 2);
        res[0] = array1[i];
        res[1] = array2[j];
        *returnSize = 2;
        return res;
      }
    }
  }
  *returnSize = 0;
  return NULL;
}

class Solution {
public:
  vector<int> findSwapValues(vector<int> &array1, vector<int> &array2) {
    long long sum1 = 0, sum2 = 0;
    for (int x : array1) sum1 += x;
    for (int x : array2) sum2 += x;
    long long diff = sum2 - sum1;
    if (diff % 2 != 0) return {};
    long long target = diff / 2;
    for (int x : array1) {
      for (int y : array2) {
        if (y == x + target) return {x, y};
      }
    }
    return {};
  }
};

