class Solution {
  public int[] findSwapValues(int[] array1, int[] array2) {
    long sum1 = 0, sum2 = 0;
    for (int x : array1) sum1 += x;
    for (int x : array2) sum2 += x;
    long diff = sum2 - sum1;
    if (diff % 2 != 0) return new int[0];
    long target = diff / 2;
    for (int x : array1) {
      for (int y : array2) {
        if (y == x + target) return new int[] { x, y };
      }
    }
    return new int[0];
  }
}

class Solution:
    def findSwapValues(self, array1: List[int], array2: List[int]) -> List[int]:
        sum1, sum2 = sum(array1), sum(array2)
        diff = sum2 - sum1
        if diff % 2 != 0:
            return []
        target = diff // 2
        set2 = set(array2)
        for x in array1:
            if x + target in set2:
                return [x, x + target]
        return []

impl Solution {
  pub fn find_swap_values(array1: Vec<i32>, array2: Vec<i32>) -> Vec<i32> {
    let sum1: i64 = array1.iter().map(|&x| x as i64).sum();
    let sum2: i64 = array2.iter().map(|&x| x as i64).sum();
    let diff = sum2 - sum1;
    if diff % 2 != 0 {
      return vec![];
    }
    let target = diff / 2;
    let set2: HashSet<i64> = array2.iter().map(|&x| x as i64).collect();
    for &x in &array1 {
      let need = x as i64 + target;
      if set2.contains(&need) {
        return vec![x, need as i32];
      }
    }
    vec![]
  }
}

const findSwapValues = (array1: number[], array2: number[]): number[] => {
  const sum1 = array1.reduce((a, b) => a + b, 0);
  const sum2 = array2.reduce((a, b) => a + b, 0);
  const diff = sum2 - sum1;
  if (diff % 2 !== 0) return [];
  const target = diff / 2;
  const set2 = new Set(array2);
  for (const x of array1) {
    if (set2.has(x + target)) return [x, x + target];
  }
  return [];
};
